1	#!/usr/bin/env tsx
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	/** The whole CLI, as a function: JSON scenario in, JSON results out. */
5	export const runCli = (input: string): string =>
6	  JSON.stringify(runScenario(JSON.parse(input) as Scenario));
7	
8	const readAll = async (stream: NodeJS.ReadableStream): Promise<string> => {
9	  const chunks: string[] = [];
10	
11	  stream.setEncoding("utf8");
12	  for await (const chunk of stream) chunks.push(chunk as string);
13	
14	  return chunks.join("");
15	};
16	
17	/**
18	 * Only wire stdin/stdout when this module is the program being run — importing
19	 * it from a test must not consume the test runner's stdin.
20	 */
21	if (process.argv[1]?.endsWith("cli.ts")) {
22	  process.stdout.write(runCli(await readAll(process.stdin)));
23	}
